      unit: bi('מגרשים · יח״ד · פרויקטים', 'lots · units · projects'), geography: bi('לפי יישוב (שווקים) · ארצי', 'By locality (markets) · national'), period: bi('כל הפעילות שנצפתה; חלונות 12 / 24 חודשים', 'All observed activity; 12 / 24-month windows'),
