      formula: bi('חוזה = f(שערים, ראיות, הערכה, תנאים, נקודות היפוך)', 'contract = f(gates, evidence, assessment, conditions, flip points)'), inputs: [bi('תמונת ההחלטה', 'the decision snapshot')],
      interpretation: bi('תלות "זזה רק עם הנחת עסקה" אינה יכולה להישבר על ידי השוק.', 'A dependency that "moves only with a deal assumption" cannot be broken by the market.'),
