      unit: bi('תשובה + העובדה + הכלל + מה לא השתנה', 'an answer + the fact + the rule + what did not change'), geography: bi('העסקה', 'The deal'), period: bi('אז מול עכשיו', 'Then vs now'), source: { ids: ['altaris:thesis', 'altaris:decision'] }, cls: 'DERIVED',
      methodology: bi('אותה כלכלה קפואה, ההערכה הנוכחית, אותם כללים F0–F5; תיקון רשמי לתקופה שקדמה להחלטה מוצג כערך מקורי לצד מתוקן והשפעתו נבחנת דרך גורם המומנטום.', 'The same frozen economics, the current assessment, the same rules F0–F5; an official revision of a pre-decision period shows the original beside the revised value and its impact is judged through the momentum factor.'),
      formula: bi('רטרו = F0–F5(כלכלה אז, הערכה עכשיו) ≟ החלטה אז', 'retro = F0–F5(economics then, assessment now) ≟ decision then'), inputs: [bi('תמונת ההחלטה; הקריאה הנוכחית; תיקונים', 'the decision snapshot; the current read; revisions')],
      interpretation: bi('"לא ניתן לקבוע" כשאין הערכת שוק עכשיו — לא "לא".', '"CANNOT DETERMINE" when there is no assessment now — not "NO".'),
      notAs: bi('לא חוכמה בדיעבד על ביצועים, לא שיפוט על מי שהחליט.', 'Not hindsight on performance, not a judgement of whoever decided.'),
