      formula: bi('עומס = |{מגרש : תחילה ∧ ¬גמר}|; השוואה = P50 / P90 של כל הקבוצות', 'load = |{lot : started ∧ ¬completed}|; comparison = P50 / P90 of every group'), inputs: [bi('השלב של כל מגרש', 'each lot\'s stage'), bi('התפלגות העומס בכל הקבוצות', 'the load distribution over every group')],
      interpretation: bi('זהו עומס נצפה — היכולת הפנימית של היזם אינה ידועה.', 'This is OBSERVED load — the developer\'s internal capacity is not known.'), notAs: bi('לא "ניצולת קיבולת" ולא הוכחה למתיחות יתר.', 'Not "capacity utilization" and not proof of over-extension.'), evidence: bi('קריאת הקבוצה — view=group → load', 'the group read — view=group → load'),
