      methodology: bi('לפחות 5 מגרשים בביצוע, מלפחות 2 מכרזים, ובאחוזון ה-90 ומעלה של הקבוצות.', 'At least 5 lots in execution, from at least 2 tenders, at or above the 90th percentile of groups.'), formula: bi('עומס ≥ 5 ∧ מכרזים ≥ 2 ∧ עומס ≥ P90', 'load ≥ 5 ∧ tenders ≥ 2 ∧ load ≥ P90'), inputs: [bi('העומס הנצפה', 'the observed load'), bi('P90 של הקבוצות', 'the groups\' P90')],
