    RENTAL_EXPANSION: { term: 'rental_tender_units_vs_stated', kind: 'watch', rule: bi('≥ 1 מגרש במסלול ההשכרה ב-24 חודשים', '≥ 1 rental-track lot in 24 months') },
    PLANNING_EVIDENCE: { term: 'units_after_plan', kind: 'info', rule: bi('≥ 2 תוכניות עם צירוף XPlan מדויק בין מגרשי היזם', '≥ 2 plans with an exact XPlan join among the developer\'s lots') },
