    POSSIBLE_SAME_ENTITY: { term: 'developer_observed_activity', kind: 'info', rule: bi('≥ 1 ישות "ייתכן שזהה" — מסומנת, לא ממוזגת', '≥ 1 "possibly the same" entity — flagged, not merged') },
    /* Live Thesis (altaris/thesis.js) — the decision-delta rules; materiality a constant per rule */
    'TH-DEAL': { term: 'reassess_vs_reunderwrite', kind: 'info', rule: bi('hash ההנחות של העסקה השמורה שונה מתמונת ההחלטה — חיתום מחדש, לא בחינה; הכלכלה מחושבת מחדש רק בגרסה חדשה', 'the saved deal\'s assumptions hash differs from the decision snapshot — a re-underwrite, not a reassessment; economics recompute only in a new version') },
    'TH-PARTIAL': { term: 'decision_delta', kind: 'info', rule: bi('קריאת PROPX חלקית (מקור לא ענה או חסר לעומת תמונת ההחלטה) — אין הערכה חדשה; כל תנאי נשאר', 'a partial PROPX read (a source did not answer or is missing against the decision snapshot) — no new assessment; every condition stays') },
    'TH-NEG-UNCOUNTABLE': { term: 'evidence_aging', kind: 'info', rule: bi('גורם שלילי שבבסיס תנאי השוק עדיין קיים אך ראיותיו נחלשו — ראיה חלשה יותר אינה פותרת תנאי', 'a negative factor behind the market condition is still present but its evidence weakened — weaker evidence never resolves a condition') },
    'TH-FIRST-ASSESSMENT': { term: 'decision_delta', kind: 'info', rule: bi('לא הייתה הערכת שוק בזמן ההחלטה — זו ההערכה הראשונה; גורמיה קריאה ראשונה, לא "חדשים מול אז"', 'no market assessment at decision time — this is the first assessment; its factors are a first read, not "new versus then"') },
    'TH-NOREAD': { term: 'decision_delta', kind: 'info', rule: bi('אין קריאת PROPX טרייה (תיק + רדאר ≤ 30 ימים) — אין הערכה חדשה; כל תנאי נשאר; ראיה חסרה אינה ראיה חיובית', 'no fresh PROPX read (dossier + radar ≤ 30 days) — no new assessment; every condition stays; missing evidence is not positive evidence') },
    'TH-F3': { term: 'decision_delta', kind: 'risk', rule: bi('ההערכה הגיעה לזהירות (≥ 2 גורמים שליליים מהותיים מ-≥ 2 משפחות) — כלל F3: TAKE → TAKE WITH CONDITIONS עם תנאי שוק', 'the assessment reached CAUTION (≥ 2 material negatives from ≥ 2 families) — rule F3: TAKE → TAKE WITH CONDITIONS with a market condition') },
