    private_land_not_observed: { label: bi('פעילות על קרקע פרטית', 'Private-land activity'), why: bi('PROPX צופה בערוצים ציבוריים בלבד (מכרזי רמ״י, הגרלות משב״ש).', 'PROPX observes public channels only (ILA tenders, MoCH lotteries).'), unlock: bi('רשימת פרויקטים מהיזם.', 'A project list from the developer.'), ids: ['private-land'] },
