    group_financials_missing: { label: bi('דוחות כספיים של ישויות הקבוצה', 'Financial statements of the group\'s entities'), why: bi('מאיה / הבורסה / מגנא חסומים ללקוח שאינו דפדפן; אין מאגר פתוח.', 'MAYA / TASE / MAGNA refuse a non-browser client; there is no open dataset.'), unlock: bi('דוחות מבוקרים (מסמך משתמש) לפי מספר החברה.', 'Audited statements (a user document) by company number.'), ids: ['group-financials'] },
    project_company_change_not_observable: { label: bi('החלפת חברת פרויקט', 'A project-company change'), why: bi('אף מקור ציבורי אינו מתעד העברת זכויות לחברת פרויקט.', 'No public source records a transfer of rights to a project company.'), unlock: bi('מסמך הזכויות העדכני.', 'The current rights document.'), ids: ['project-company-change'] },
    group_sales_missing: { label: bi('מכירות ברמת הפרויקט', 'Project-level sales'), why: bi('אין מקור ציבורי למכירות של יזם.', 'There is no public source for a developer\'s sales.'), unlock: bi('דוח מכירות (מסמך משתמש, דיווח עצמי).', 'A sales report (a user document, self-reported).'), ids: ['group-sales'] },
