    ownership_not_in_coverage: { label: bi("מבנה בעלות", "Ownership structure"), why: bi("המאגר הפתוח של הרשם אינו כולל בעלי מניות; אם / בת / SPV / ערב אינם נקבעים.", "The open Registrar dataset carries no shareholders; parent / subsidiary / SPV / guarantor are not determined."), unlock: bi("נסח רשם מלא והסכם הפרויקט.", "A full Registrar extract and the project agreement."), ids: ["ownership"] },
