    litigation_not_in_coverage: { label: bi("הליכים משפטיים אזרחיים", "Civil litigation"), why: bi("אין מאגר פתוח ברמת הנתבע; נט המשפט הוא שירות מזוהה.", "No open defendant-level dataset; the court system is a login service."), unlock: bi("בדיקה ידנית בנט המשפט לפי מספר החברה.", "A manual court-system search by company number."), ids: ["litigation"] },
    executing_contractor_unknown: { label: bi("הקבלן המבצע של הפרויקט", "The project's executing contractor"), why: bi("נראה רק באתר שמצטרף לפרויקט במפתח.", "Visible only on a site that joins the project by a key."), unlock: bi("שם ומספר הקבלן מהיזם.", "The contractor's name and number from the developer."), ids: ["executing-contractor"] },
    permits_outside_tlv: { label: bi("היתר / תחילת בנייה מחוץ לתל אביב", "Permit / construction start outside Tel Aviv"), why: bi("אין מקור עירוני קריא למכונה מחוץ לתל אביב-יפו.", "No machine-readable municipal source outside Tel Aviv-Yafo."), unlock: bi("מספר ההיתר ותאריך תחילת העבודה מהיזם / מהרשות המקומית.", "The permit number and the work-start date from the developer / the municipality."), ids: ["permits-outside-tlv"] },
