    /* CBS construction (lib/construction) */
    no_construction_series: { label: bi('סדרות הבנייה של הלמ״ס טרם נקראו', 'CBS construction series not loaded yet'), why: bi('הסנכרון הראשון של היתרים · התחלות · גמר · בנייה פעילה ממתין (ימי עבודה, GitHub Actions); צנרת ההיצע מציגה את יקומי הלמ״ס רק אחריו.', 'The first sync of permits · starts · completions · active construction is pending (working days, GitHub Actions); the supply pipeline shows the CBS universes only after it.'), unlock: bi('ריצה מוצלחת של construction-sync', 'a successful construction-sync run'), ids: ['construction-series', 'construction-cbs'] },
    no_locality_construction_series: { label: bi('אין סדרת בנייה ליישוב', 'No locality construction series'), why: bi('הלמ״ס מפרסמת היתרים · התחלות · גמר · בנייה פעילה ארצי ולפי מחוז בלבד; נתון המחוז מוצג ומסומן כהקשר, לעולם לא מוקצה ליישוב.', 'CBS publishes permits · starts · completions · active construction nationally and by district only; the district figure is shown and labelled as context, never allocated to the locality.'), unlock: bi('סדרה עירונית רשמית (אין כיום) או היתרי הרשות המקומית', 'an official city series (none today) or the municipality\'s permits'), ids: ['construction-locality'] },
    /* land economics */
    no_all_in_land_cost: { label: bi('אין עלות קרקע כוללת ליח״ד', 'No all-in land cost per unit'), why: bi('הוצאות הפיתוח מדווחות בנפרד (לא לכל מגרש), מע״מ אינו מצוין במקור, והתמורה נומינלית — PROPX אינה מחברת.', 'Development costs are reported apart (not for every lot), VAT is not stated by the source, and the consideration is nominal — PROPX does not add them up.'), unlock: bi('מקור שמפרסם הוצאות פיתוח ומע״מ לכל מגרש.', 'A source publishing development costs and VAT per lot.'), ids: ['development-costs'] },
    /* project intelligence */
